import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

test("A certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ apiAs, factory }) => {
  // Arrange: the server's "today" is the UTC date, so the certificate expires on that same day.
  const today = new Date().toISOString().slice(0, 10);
  const vendor = await factory.vendor({ as: "member" });
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  const member = await apiAs("member");
  const certificate = Buffer.from(
    `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${today}\n`,
  );
  await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: { name: "insurance_certificate.txt", mimeType: "text/plain", buffer: certificate },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () => {
        const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
  expect(documents.map((d) => d.kind)).toContain("insurance_certificate");
  const insurance = documents.find((d) => d.kind === "insurance_certificate") as Document;
  const pending = await factory.extraction(insurance.id, "member");
  expect(pending.status).toBe("pending_review");

  // Act
  const reviewer = await apiAs("reviewer");
  const response = await reviewer.post(`/api/extractions/${pending.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const decided = await expectStatus<Extraction>(response, 200);
  expect(decided.status).toBe("approved");
  const stored = await factory.extraction(insurance.id, "reviewer");
  expect(stored.status).toBe("approved");
});
